38	//--------------------------------------------------------------------------
39	// Description:
40	//   Poly1305 library
41	//==========================================================================
42	
43	#include "poly1305.h"
44	#include "string_bare.h"
45	
46	#define BLOCK_SIZE 16
47	
48	/**
49	 * @brief 130-bit prime: 2^130 - 5
50	 */
51	static const uint64_t PRIME[3] = {0xFFFFFFFFFFFFFFFB, 0xFFFFFFFFFFFFFFFF, 0x3};
52	
53	/**
54	 * @brief Structure to hold a 320-bit unsigned integer for Poly1305 calculations
55	 */
56	typedef struct
57	{
58	    uint64_t limbs[5]; // 64-bit limbs
59	} uint320_t;
60	
61	/**
62	 * @brief Apply clamping to the 'r' part of the key
63	 *
64	 * @param r 16-byte array to clamp
65	 */
66	static void clamp(uint8_t r[16])
67	{
68	    r[3] &= 15;
69	    r[7] &= 15;
70	    r[11] &= 15;
71	    r[15] &= 15;
72	    r[4] &= 252;
73	    r[8] &= 252;
74	    r[12] &= 252;
75	}
76	
77	/**
78	 * @brief Copy bytes to a uint320_t
79	 *
80	 * @param dst Destination uint320_t
81	 * @param src Source byte array
82	 * @param len Number of bytes to copy (max 40)
83	 */
84	static void bytes_to_uint320(uint320_t *dst, const uint8_t *src, size_t len)
85	{
86	    memset(dst->limbs, 0, sizeof(dst->limbs));
87	
88	    for (size_t i = 0; i < len && i < 40; i++)
89	    {
90	        size_t limb_idx = i / 8;
91	        size_t bit_shift = (i % 8) * 8;
92	        dst->limbs[limb_idx] |= ((uint64_t)src[i]) << bit_shift;
93	    }
94	}
95	
96	/**
97	 * @brief Add two uint320_t values
98	 *
99	 * @param res Result: a + b
100	 * @param a First operand
101	 * @param b Second operand
102	 */
103	static void uint320_add(uint320_t *res, const uint320_t *a, const uint320_t *b)
104	{
105	    uint64_t carry = 0;
106	
107	    for (int i = 0; i < 5; i++)
108	    {
109	        uint64_t sum = a->limbs[i] + b->limbs[i] + carry;
110	        carry = (sum < a->limbs[i]) || (sum == a->limbs[i] && carry);
111	        res->limbs[i] = sum;
112	    }
113	}
114	
115	/**
116	 * @brief Multiply two uint320_t values
117	 *
118	 * @param res Result: a * b
119	 * @param a First operand
120	 * @param b Second operand
121	 */
122	static void uint320_mul(uint320_t *res, const uint320_t *a, const uint320_t *b)
123	{
124	    uint320_t temp;
125	    memset(&temp, 0, sizeof(temp));
126	
127	    // Schoolbook multiplication algorithm
128	    for (int i = 0; i < 5; i++)
129	    {
130	        uint64_t carry = 0;
131	        for (int j = 0; j < 5 - i; j++)
132	        {
133	            uint64_t high;
134	            uint64_t low;
135	            uint64_t product = a->limbs[i] * b->limbs[j];
136	            uint64_t old_value = temp.limbs[i + j];
137	
138	            // Add previous value and carry
139	            low = product + old_value;
140	            high = (low < product) ? 1 : 0;
141	            low += carry;
142	            high += (low < carry) ? 1 : 0;
143	
144	            temp.limbs[i + j] = low;
145	            carry = high;
146	        }
147	    }
148	
149	    memcpy(res, &temp, sizeof(uint320_t));
150	}
151	
152	/**
153	 * @brief Reduce a uint320_t modulo 2^130 - 5
154	 *
155	 * @param a Value to reduce
156	 */
157	static void uint320_mod_prime(uint320_t *a)
158	{
159	    // First, handle the high bits (greater than or equal to 2^130)
160	    uint64_t mask = 0x3FFFFFFFFFF; // 2^130 - 1
161	    uint64_t high_bits = a->limbs[2] & ~mask;
162	    if (high_bits || a->limbs[3] || a->limbs[4])
163	    {
164	        // We have bits above 2^130, need to reduce
165	
166	        // Clear high bits
167	        a->limbs[2] &= mask;
168	        a->limbs[3] = 0;
169	        a->limbs[4] = 0;
170	
171	        // Multiply high bits by 5 and add to low bits
172	        uint320_t mul5;
173	        memset(&mul5, 0, sizeof(mul5));
174	
175	        // high_bits * 5
176	        mul5.limbs[0] = (high_bits >> 2) * 5;
177	
178	        // Add to original value
179	        uint320_add(a, a, &mul5);
180	    }
181	
182	    // Check if result is still >= 2^130 - 5
183	    if ((a->limbs[2] & mask) == mask &&
184	        a->limbs[1] == 0xFFFFFFFFFFFFFFFF &&
185	        a->limbs[0] >= 0xFFFFFFFFFFFFFFFB)
186	    {
187	
188	        // Subtract 2^130 - 5
189	        uint64_t borrow = 0;
190	        uint64_t diff;
191	
192	        diff = a->limbs[0] - 0xFFFFFFFFFFFFFFFB;
193	        borrow = (diff > a->limbs[0]) ? 1 : 0;
194	        a->limbs[0] = diff;
195	
196	        diff = a->limbs[1] - 0xFFFFFFFFFFFFFFFF - borrow;
197	        borrow = (diff > a->limbs[1]) || (diff == a->limbs[1] && borrow);
198	        a->limbs[1] = diff;
199	
200	        a->limbs[2] -= borrow;
201	        a->limbs[2] &= mask; // Ensure top bits are zero
202	    }
203	}
204	
205	/**
206	 * @brief Compute Poly1305 MAC for a message
207	 *
208	 * @param auth_tag Output buffer for the 16-byte authentication tag
209	 * @param key 32-byte key (r || s)
210	 * @param message Input message buffer
211	 * @param message_length Length of the message in bytes
212	 */
213	void poly1305_mac(uint8_t *auth_tag, const uint8_t *key, const uint8_t *message, size_t message_length)
214	{
215	    uint8_t r_bytes[16]; // r part of the key
216	    uint8_t s_bytes[16]; // s part of the key
217	
218	    // Split key into r and s components
219	    memcpy(r_bytes, key, 16);
220	    memcpy(s_bytes, key + 16, 16);
221	
222	    // Clamp r according to the spec
223	    clamp(r_bytes);
224	
225	    // Convert r and s to uint320_t
226	    uint320_t r, s, a;
227	    memset(&a, 0, sizeof(a)); // Initialize accumulator to 0
228	    bytes_to_uint320(&r, r_bytes, 16);
229	    bytes_to_uint320(&s, s_bytes, 16);
230	
231	    // Process message in 16-byte blocks
232	    size_t blocks = message_length / BLOCK_SIZE;
233	    size_t remain = message_length % BLOCK_SIZE;
234	
235	    // Process full blocks
236	    for (size_t i = 0; i < blocks; i++)
237	    {
238	        uint320_t n;
239	        bytes_to_uint320(&n, message + (i * BLOCK_SIZE), BLOCK_SIZE);
240	
241	        // Set the high bit (2^128)
242	        n.limbs[2] |= 0x1;
243	
244	        // a += n
245	        uint320_add(&a, &a, &n);
246	
247	        // a *= r
248	        uint320_t temp = a;
249	        uint320_mul(&a, &temp, &r);
250	
251	        // a %= p
252	        uint320_mod_prime(&a);
253	    }
254	
255	    // Process remaining bytes
256	    if (remain > 0)
257	    {
258	        uint8_t last_block[BLOCK_SIZE] = {0};
259	        memcpy(last_block, message + (blocks * BLOCK_SIZE), remain);
260	
261	        // Add the padding byte
262	        last_block[remain] = 0x01;
263	
264	        uint320_t n;
265	        bytes_to_uint320(&n, last_block, BLOCK_SIZE);
266	
267	        // a += n
268	        uint320_add(&a, &a, &n);
269	
270	        // a *= r
271	        uint320_t temp = a;
272	        uint320_mul(&a, &temp, &r);
273	
274	        // a %= p
275	        uint320_mod_prime(&a);
276	    }
277	
278	    // a += s
279	    uint320_add(&a, &a, &s);
280	
281	    // Copy the first 16 bytes to output
282	    memcpy(auth_tag, &a, 16);
283	}
284	
285	/**
286	 * @brief Verify if two Poly1305 tags match
287	 *
288	 * @param tag1 First tag to compare
289	 * @param tag2 Second tag to compare
290	 * @return 1 if tags match, 0 otherwise
291	 */
292	int poly1305_verify(const uint8_t *tag1, const uint8_t *tag2)
293	{
294	    uint64_t *a_hi = (uint64_t *)(tag1);
295	    uint64_t *a_lo = (uint64_t *)(tag1 + 8);
296	    uint64_t *b_hi = (uint64_t *)(tag2);
297	    uint64_t *b_lo = (uint64_t *)(tag2 + 8);
298	
299	    return (a_hi[0] == b_hi[0]) && (a_lo[0] == b_lo[0]);
300	}
