/**
 * @file chacha20.h
 * @brief Simple implementation of ChaCha20 encription algorithm
 */

#ifndef CHACHA20_H
#define CHACHA20_H

#ifdef __cplusplus
extern "C" {
#endif

#include <stddef.h>
#include <stdint.h>

#define CHACHA20_KEY_SIZE 32
#define CHACHA20_NONCE_SIZE 12
#define CHACHA20_BLOCK_SIZE 64

// ChaCha20 state structure
typedef struct
{
    uint32_t state[16]; // ChaCha20 state (16 words)
} chacha20_state;

/**
 * @brief Initializes the ChaCha20 state with the given key, nonce, and counter.
 *
 * @param state Pointer to the 16-word state array.
 * @param key Pointer to the 32-byte encryption key.
 * @param nonce Pointer to the 12-byte nonce.
 * @param counter Initial counter value.
 */
void chacha20_init(chacha20_state *state, const uint8_t *key, const uint8_t *nonce, uint32_t counter);

/**
 * @brief Encrypts data using the ChaCha20 stream cipher.
 *
 * @param out Pointer to the output ciphertext buffer.
 * @param in Pointer to the input plaintext buffer.
 * @param length Number of bytes to encrypt.
 * @param key Pointer to the 32-byte encryption key.
 * @param nonce Pointer to the 12-byte nonce.
 * @param counter Initial counter value.
 */
void chacha20_encrypt(uint8_t *out, const uint8_t *in, size_t length, const uint8_t *key, const uint8_t *nonce, uint32_t counter);

/**
 * @brief Decrypts data using the ChaCha20 stream cipher (same as encryption).
 */
#define chacha20_decrypt chacha20_encrypt

void chacha20_block(chacha20_state *state, chacha20_state *output);

#ifdef __cplusplus
}
#endif

#endif // CHACHA20_H

// SPDX-FileCopyrightText: 2026 Chili.CHIPS*ba
//
// SPDX-License-Identifier: BSD-3-Clause

/**
 * @file poly1305.h
 * @brief Simple implementation of Poly1305 MAC algorithm
 */

#ifndef POLY1305_H
#define POLY1305_H

#ifdef __cplusplus
extern "C" {
#endif

#include <stdint.h>
#include <stddef.h>

/**
 * @brief Compute Poly1305 MAC for a message
 *
 * @param auth_tag Output buffer for the 16-byte authentication tag
 * @param key 32-byte key (r || s)
 * @param message Input message buffer
 * @param message_length Length of the message in bytes
 */
void poly1305_mac(uint8_t *auth_tag, const uint8_t *key, const uint8_t *message, size_t message_lenght);

/**
 * @brief Verify if two Poly1305 tags match
 *
 * @param received_auth_tag Received tag to compare
 * @param calucalted_auth_tag Calculated tag to compare
 * @return 1 if tags match, 0 otherwise
 */
int poly1305_verify(const uint8_t *received_auth_tag, const uint8_t *calucalted_auth_tag);

#ifdef __cplusplus
}
#endif

#endif // POLY1305_H

